import csv
import json
import math
from datetime import datetime
from collections import defaultdict

# ── Load data ──────────────────────────────────────────────────────────────
rows = []
with open('/app/benchmark/data.csv', 'r') as f:
    reader = csv.DictReader(f)
    for r in reader:
        rows.append({
            'date': datetime.strptime(r['Date'], '%Y-%m-%d'),
            'price': float(r['Crude_Oil_Price'])
        })

rows.sort(key=lambda r: r['date'])
prices = [r['price'] for r in rows]
dates = [r['date'] for r in rows]
n = len(rows)

# ── Basic stats ────────────────────────────────────────────────────────────
min_price = min(prices)
max_price = max(prices)
min_idx = prices.index(min_price)
max_idx = prices.index(max_price)
price_range = max_price - min_price
mean_price = sum(prices) / n
median_price = sorted(prices)[n // 2]
std_dev = math.sqrt(sum((p - mean_price) ** 2 for p in prices) / n)

# Percentiles
sp = sorted(prices)
def pctile(pct):
    k = int(math.ceil((pct / 100) * n)) - 1
    return sp[max(0, min(k, n - 1))]

p25 = pctile(25)
p50 = median_price
p75 = pctile(75)
p10 = pctile(10)
p90 = pctile(90)

# ── CAGR ───────────────────────────────────────────────────────────────────
first_price = prices[0]
last_price = prices[-1]
first_date = dates[0]
last_date = dates[-1]
years = (last_date - first_date).days / 365.25
cagr = (last_price / first_price) ** (1 / years) - 1

# ── MoM changes ────────────────────────────────────────────────────────────
mom_changes = []
mom_pct_changes = []
for i in range(1, n):
    abs_chg = prices[i] - prices[i - 1]
    pct_chg = (prices[i] - prices[i - 1]) / prices[i - 1] * 100
    mom_changes.append({'date': dates[i], 'abs': abs_chg, 'pct': pct_chg})
    mom_pct_changes.append(pct_chg)

max_mom_increase = max(mom_changes, key=lambda x: x['abs'])
max_mom_decrease = min(mom_changes, key=lambda x: x['abs'])
max_mom_pct_increase = max(mom_changes, key=lambda x: x['pct'])
max_mom_pct_decrease = min(mom_changes, key=lambda x: x['pct'])

# ── YoY changes ────────────────────────────────────────────────────────────
yoy_changes = []
for i in range(12, n):
    yoy_abs = prices[i] - prices[i - 12]
    yoy_pct = (prices[i] - prices[i - 12]) / prices[i - 12] * 100
    yoy_changes.append({'date': dates[i], 'abs': yoy_abs, 'pct': yoy_pct})

# ── Decade analysis ────────────────────────────────────────────────────────
decades = defaultdict(list)
for r in rows:
    d = (r['date'].year // 10) * 10
    decades[d].append(r['price'])

decade_stats = {}
for dec in sorted(decades.keys()):
    vals = decades[dec]
    decade_stats[dec] = {
        'avg': sum(vals) / len(vals),
        'min': min(vals),
        'max': max(vals),
        'std': math.sqrt(sum((v - sum(vals)/len(vals))**2 for v in vals) / len(vals)),
        'count': len(vals),
    }

highest_avg_decade = max(decade_stats, key=lambda d: decade_stats[d]['avg'])

# ── Yearly averages ────────────────────────────────────────────────────────
yearly = defaultdict(list)
for r in rows:
    yearly[r['date'].year].append(r['price'])
yearly_avg = {yr: sum(vals)/len(vals) for yr, vals in sorted(yearly.items())}

# ── Monthly volatility (std dev of MoM % changes by decade) ────────────────
decade_volatility = {}
for dec in sorted(decades.keys()):
    dec_mom_pct = []
    dec_prices = [(r['date'], r['price']) for r in rows if (r['date'].year // 10) * 10 == dec]
    dec_prices.sort()
    dec_vals = [p for _, p in dec_prices]
    for i in range(1, len(dec_vals)):
        dec_mom_pct.append(abs((dec_vals[i] - dec_vals[i-1]) / dec_vals[i-1] * 100))
    if dec_mom_pct:
        decade_volatility[dec] = sum(dec_mom_pct) / len(dec_mom_pct)

# ── Rolling 12-month volatility ────────────────────────────────────────────
rolling_vol_12 = []
for i in range(11, n):
    window = prices[i - 11:i + 1]
    w_mean = sum(window) / 12
    w_std = math.sqrt(sum((x - w_mean) ** 2 for x in window) / 12)
    rolling_vol_12.append({'date': dates[i], 'std': w_std})

# ── Top 10 MoM shocks ──────────────────────────────────────────────────────
top_mom_increases = sorted(mom_changes, key=lambda x: -x['abs'])[:10]
top_mom_decreases = sorted(mom_changes, key=lambda x: x['abs'])[:10]

# ── Generate HTML report ───────────────────────────────────────────────────

def fmt_price(p):
    return f"${p:,.2f}"

def fmt_date(d):
    return d.strftime('%B %Y')

def decade_label(d):
    return f"{d}s"

# Prepare chart data as JSON
chart_labels = [r['date'].strftime('%Y-%m-%d') for r in rows]
chart_prices = [round(r['price'], 4) for r in rows]

# Yearly avg chart
yearly_years = list(yearly_avg.keys())[1:]  # skip 1970 partial context - actually keep all
yearly_years = list(yearly_avg.keys())
yearly_vals = [round(yearly_avg[y], 2) for y in yearly_years]

# Decade bar chart
decade_order = sorted(decade_stats.keys())
decade_avgs = [round(decade_stats[d]['avg'], 2) for d in decade_order]
decade_stds = [round(decade_stats[d]['std'], 2) for d in decade_order]
decade_labels = [decade_label(d) for d in decade_order]

# Rolling vol chart
rv_dates = [rv['date'].strftime('%Y-%m-%d') for rv in rolling_vol_12]
rv_vals = [round(rv['std'], 2) for rv in rolling_vol_12]

# MoM change chart (last ~60 months for readability in a sub-chart, plus full series)
mom_labels = [mc['date'].strftime('%Y-%m-%d') for mc in mom_changes]
mom_abs_vals = [round(mc['abs'], 4) for mc in mom_changes]

# Distribution histogram data
hist_bins = 30
bin_width = (max_price - min_price) / hist_bins
hist_counts = [0] * hist_bins
hist_bin_edges = [round(min_price + i * bin_width, 2) for i in range(hist_bins + 1)]
for p in prices:
    b = min(int((p - min_price) / bin_width), hist_bins - 1)
    hist_counts[b] += 1
hist_labels_bin = [f"${hist_bin_edges[i]:.0f}-${hist_bin_edges[i+1]:.0f}" for i in range(hist_bins)]

# Box plot data per decade
boxplot_data = {}
for d in decade_order:
    vals = sorted(decades[d])
    nv = len(vals)
    boxplot_data[decade_label(d)] = {
        'min': round(min(vals), 2),
        'q1': round(vals[nv//4], 2),
        'median': round(vals[nv//2], 2),
        'q3': round(vals[3*nv//4], 2),
        'max': round(max(vals), 2),
    }

html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Crude Oil Price Trends: A Historical Analysis (1970–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --bg: #0d1117;
    --card-bg: #161b22;
    --border: #30363d;
    --text: #c9d1d9;
    --text-secondary: #8b949e;
    --accent: #58a6ff;
    --accent2: #f0883e;
    --green: #3fb950;
    --red: #f85149;
    --purple: #bc8cff;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
  }}
  .container {{ max-width: 1200px; margin: 0 auto; padding: 20px 24px; }}
  header {{
    background: var(--card-bg);
    border-bottom: 1px solid var(--border);
    padding: 32px 0;
    margin-bottom: 32px;
  }}
  header h1 {{ font-size: 1.8rem; font-weight: 700; color: #fff; margin-bottom: 6px; }}
  header .subtitle {{ color: var(--text-secondary); font-size: 0.95rem; }}
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 16px;
    margin-bottom: 32px;
  }}
  .kpi-card {{
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 18px 20px;
  }}
  .kpi-card .label {{ font-size: 0.78rem; color: var(--text-secondary); text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 4px; }}
  .kpi-card .value {{ font-size: 1.55rem; font-weight: 700; color: #fff; }}
  .kpi-card .detail {{ font-size: 0.78rem; color: var(--text-secondary); margin-top: 2px; }}
  section {{ margin-bottom: 40px; }}
  section h2 {{
    font-size: 1.35rem;
    color: #fff;
    border-bottom: 1px solid var(--border);
    padding-bottom: 10px;
    margin-bottom: 20px;
  }}
  section h3 {{ font-size: 1.1rem; color: var(--accent); margin: 24px 0 12px; }}
  section p {{ color: var(--text-secondary); margin-bottom: 12px; }}
  .chart-card {{
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 20px;
    margin-bottom: 20px;
  }}
  .chart-card h4 {{ font-size: 0.9rem; color: var(--text); margin-bottom: 12px; }}
  .chart-wrap {{ position: relative; width: 100%; }}
  .chart-wrap canvas {{ width: 100% !important; }}
  table {{
    width: 100%;
    border-collapse: collapse;
    font-size: 0.88rem;
    margin: 16px 0;
  }}
  th, td {{
    padding: 10px 14px;
    text-align: left;
    border-bottom: 1px solid var(--border);
  }}
  th {{ background: var(--card-bg); color: var(--text); font-weight: 600; text-transform: uppercase; font-size: 0.75rem; letter-spacing: 0.04em; }}
  td {{ color: var(--text-secondary); }}
  .highlight {{ color: #fff; font-weight: 600; }}
  .pos {{ color: var(--green); }}
  .neg {{ color: var(--red); }}
  .two-col {{ display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }}
  @media (max-width: 768px) {{ .two-col {{ grid-template-columns: 1fr; }} }}
  .bullet-list {{ list-style: none; padding: 0; }}
  .bullet-list li {{ padding: 6px 0; color: var(--text-secondary); }}
  .bullet-list li::before {{ content: "▸ "; color: var(--accent); }}
  footer {{
    border-top: 1px solid var(--border);
    padding: 24px 0;
    text-align: center;
    color: var(--text-secondary);
    font-size: 0.8rem;
  }}
</style>
</head>
<body>

<header>
  <div class="container">
    <h1>Global Crude Oil Price Trends: A Historical Analysis (1970–2026)</h1>
    <p class="subtitle">Comprehensive trend analysis of monthly crude oil prices spanning over five decades. Prepared for energy market analysts, macroeconomic researchers, and commodity strategists.</p>
    <p class="subtitle" style="margin-top:4px;">Dataset: {n} monthly observations &middot; {fmt_date(first_date)} – {fmt_date(last_date)} &middot; Nominal USD/bbl</p>
  </div>
</header>

<div class="container">

<!-- ── SECTION 1: EXECUTIVE OVERVIEW ───────────────────────────────────── -->
<section id="executive-overview">
  <h2>1. Executive Overview</h2>

  <div class="kpi-grid">
    <div class="kpi-card">
      <div class="label">Overall Price Range</div>
      <div class="value">{fmt_price(min_price)} – {fmt_price(max_price)}</div>
      <div class="detail">Span of {fmt_price(price_range)} across {n} monthly observations</div>
    </div>
    <div class="kpi-card">
      <div class="label">CAGR ({years:.1f} years)</div>
      <div class="value">{cagr * 100:.2f}%</div>
      <div class="detail">{fmt_date(first_date)} → {fmt_date(last_date)}</div>
    </div>
    <div class="kpi-card">
      <div class="label">Max Month-over-Month Change</div>
      <div class="value">{fmt_price(max_mom_increase['abs'])}</div>
      <div class="detail">{max_mom_pct_increase['pct']:.1f}% increase — {fmt_date(max_mom_increase['date'])}</div>
    </div>
    <div class="kpi-card">
      <div class="label">Decade with Highest Avg Price</div>
      <div class="value">{decade_label(highest_avg_decade)}</div>
      <div class="detail">Average: {fmt_price(decade_stats[highest_avg_decade]['avg'])}</div>
    </div>
    <div class="kpi-card">
      <div class="label">Price Volatility (Std Dev)</div>
      <div class="value">{fmt_price(std_dev)}</div>
      <div class="detail">Long-term price dispersion from mean of {fmt_price(mean_price)}</div>
    </div>
  </div>

  <p>This report examines the full trajectory of global crude oil prices from January 1970 to March 2026, covering {n} monthly data points. Over this {years:.0f}-year span, crude oil has transitioned from a low, stable-priced commodity (starting at {fmt_price(first_price)}) through multiple price regimes — the oil shocks of the 1970s, the collapse of the mid-1980s, the super-cycle of the 2000s, the 2020 pandemic demand shock, and the post-2022 geopolitical repricing. The compounded annual growth rate of <strong>{cagr * 100:.2f}%</strong> reflects this long-term ascent, though the path has been anything but smooth: the standard deviation of monthly prices ({fmt_price(std_dev)}) is {std_dev / mean_price * 100:.0f}% of the mean, underscoring extreme episodic volatility.</p>

  <p>The single largest month-over-month price shock was a <strong class="neg">{max_mom_pct_decrease['pct']:.1f}%</strong> decline in {fmt_date(max_mom_pct_decrease['date'])}. The largest monthly increase was <strong class="pos">{max_mom_pct_increase['pct']:.1f}%</strong> in {fmt_date(max_mom_pct_increase['date'])}. These extremes illustrate the asymmetric risk profile of crude oil as an asset class.</p>
</section>

<!-- ── SECTION 2: LONG-TERM PRICE TRAJECTORY ───────────────────────────── -->
<section id="long-term-trend">
  <h2>2. Long-Term Price Trajectory (1970–2026)</h2>
  <p>The full monthly time series reveals distinct price regimes driven by geopolitics, supply dynamics, and macroeconomic cycles. Key inflection points include the 1973–74 oil embargo, the 1979 Iranian Revolution, the 1986 price collapse, the 1990 Gulf War spike, the 2008 super-spike and subsequent crash, the 2014–15 shale-driven correction, the 2020 COVID-19 demand shock, and the 2022 Russia-Ukraine price surge.</p>

  <div class="chart-card">
    <h4>Monthly Crude Oil Price (USD/bbl) — Full Time Series</h4>
    <div class="chart-wrap"><canvas id="fullSeriesChart"></canvas></div>
  </div>

  <div class="chart-card">
    <h4>Annual Average Crude Oil Price</h4>
    <div class="chart-wrap"><canvas id="yearlyAvgChart"></canvas></div>
  </div>

  <p>The all-time nominal peak was recorded in <strong>{fmt_date(dates[max_idx])}</strong> at <strong>{fmt_price(max_price)}</strong>. The all-time low was <strong>{fmt_price(min_price)}</strong> in <strong>{fmt_date(dates[min_idx])}</strong>. The price range of <strong>{fmt_price(price_range)}</strong> represents a {price_range / min_price:.0f}x multiple between the minimum and maximum monthly observations.</p>
</section>

<!-- ── SECTION 3: DECADE-BY-DECADE ─────────────────────────────────────── -->
<section id="decade-by-decade">
  <h2>3. Decade-by-Decade Breakdown</h2>
  <p>Decomposing the data by decade reveals the structural evolution of the global crude oil market — from the relatively tranquil pre-1973 era to the high-volatility environment of the 2000s onward.</p>

  <div class="chart-card">
    <h4>Average Monthly Price by Decade (with Standard Deviation)</h4>
    <div class="chart-wrap"><canvas id="decadeBarChart"></canvas></div>
  </div>

  <div class="chart-card">
    <h4>Price Distribution by Decade (Box Plot)</h4>
    <div class="chart-wrap"><canvas id="decadeBoxPlot"></canvas></div>
  </div>

  <table>
    <thead>
      <tr><th>Decade</th><th>Avg Price</th><th>Min</th><th>Max</th><th>Std Dev</th><th>Months</th><th>Avg |MoM%|</th></tr>
    </thead>
    <tbody>
'''
for d in decade_order:
    ds = decade_stats[d]
    vol = decade_volatility.get(d, 0)
    html += f'      <tr><td class="highlight">{decade_label(d)}</td><td>{fmt_price(ds["avg"])}</td><td>{fmt_price(ds["min"])}</td><td>{fmt_price(ds["max"])}</td><td>{fmt_price(ds["std"])}</td><td>{ds["count"]}</td><td>{vol:.2f}%</td></tr>\n'

html += '''    </tbody>
  </table>

  <h3>1970s — The Oil Shock Decade</h3>
  <p>The 1970s saw crude oil transition from a stable, low-cost commodity ($1.21–$2.70 in 1970–1973) to a geopolitically weaponized asset. The 1973 Arab Oil Embargo drove prices from $4.10 in October 1973 to $13.00 by January 1974 — a threefold increase in three months. The 1979 Iranian Revolution triggered a second shock, pushing prices from ~$14.50 in December 1978 to $40.75 by November 1979 — nearly tripling in under a year. By the end of the decade, crude had established itself as a volatile, strategically critical commodity.</p>

  <h3>1980s — Boom, Bust, and the 1986 Collapse</h3>
  <p>The early 1980s saw elevated but gradually declining prices as conservation efforts and new non-OPEC supply (North Sea, Alaska) came online. The defining event was the 1986 price collapse: from $24.68 in January 1986 to $9.62 by July 1986 — a 61% decline driven by Saudi Arabia's decision to abandon the swing producer role and flood the market. Prices recovered modestly through the late 1980s but remained in a $12–$20 range.</p>

  <h3>1990s — Relative Stability and the Asian Financial Crisis</h3>
