import csv
import json
import math
from datetime import datetime
from collections import defaultdict

# ── Load data ──────────────────────────────────────────────────────────────
rows = []
with open('/app/benchmark/data.csv', 'r') as f:
    reader = csv.DictReader(f)
    for r in reader:
        rows.append({
            'date': datetime.strptime(r['Date'], '%Y-%m-%d'),
            'price': float(r['Crude_Oil_Price'])
        })

rows.sort(key=lambda r: r['date'])
prices = [r['price'] for r in rows]
dates = [r['date'] for r in rows]
n = len(rows)

# ── Basic stats ────────────────────────────────────────────────────────────
min_price = min(prices)
max_price = max(prices)
min_idx = prices.index(min_price)
max_idx = prices.index(max_price)
price_range = max_price - min_price
mean_price = sum(prices) / n
median_price = sorted(prices)[n // 2]
std_dev = math.sqrt(sum((p - mean_price) ** 2 for p in prices) / n)

# Percentiles
sp = sorted(prices)
def pctile(pct):
    k = int(math.ceil((pct / 100) * n)) - 1
    return sp[max(0, min(k, n - 1))]

p25 = pctile(25)
p50 = median_price
p75 = pctile(75)
p10 = pctile(10)
p90 = pctile(90)

# ── CAGR ───────────────────────────────────────────────────────────────────
first_price = prices[0]
last_price = prices[-1]
first_date = dates[0]
last_date = dates[-1]
years = (last_date - first_date).days / 365.25
cagr = (last_price / first_price) ** (1 / years) - 1

# ── MoM changes ────────────────────────────────────────────────────────────
mom_changes = []
mom_pct_changes = []
for i in range(1, n):
    abs_chg = prices[i] - prices[i - 1]
    pct_chg = (prices[i] - prices[i - 1]) / prices[i - 1] * 100
    mom_changes.append({'date': dates[i], 'abs': abs_chg, 'pct': pct_chg})
    mom_pct_changes.append(pct_chg)

max_mom_increase = max(mom_changes, key=lambda x: x['abs'])
max_mom_decrease = min(mom_changes, key=lambda x: x['abs'])
max_mom_pct_increase = max(mom_changes, key=lambda x: x['pct'])
max_mom_pct_decrease = min(mom_changes, key=lambda x: x['pct'])

# ── YoY changes ────────────────────────────────────────────────────────────
yoy_changes = []
for i in range(12, n):
    yoy_abs = prices[i] - prices[i - 12]
    yoy_pct = (prices[i] - prices[i - 12]) / prices[i - 12] * 100
    yoy_changes.append({'date': dates[i], 'abs': yoy_abs, 'pct': yoy_pct})

# ── Decade analysis ────────────────────────────────────────────────────────
decades = defaultdict(list)
for r in rows:
    d = (r['date'].year // 10) * 10
    decades[d].append(r['price'])

decade_stats = {}
for dec in sorted(decades.keys()):
    vals = decades[dec]
    decade_stats[dec] = {
        'avg': sum(vals) / len(vals),
        'min': min(vals),
        'max': max(vals),
        'std': math.sqrt(sum((v - sum(vals)/len(vals))**2 for v in vals) / len(vals)),
        'count': len(vals),
    }

highest_avg_decade = max(decade_stats, key=lambda d: decade_stats[d]['avg'])

# ── Yearly averages ────────────────────────────────────────────────────────
yearly = defaultdict(list)
for r in rows:
    yearly[r['date'].year].append(r['price'])
yearly_avg = {yr: sum(vals)/len(vals) for yr, vals in sorted(yearly.items())}

# ── Monthly volatility (std dev of MoM % changes by decade) ────────────────
decade_volatility = {}
for dec in sorted(decades.keys()):
    dec_mom_pct = []
    dec_prices = [(r['date'], r['price']) for r in rows if (r['date'].year // 10) * 10 == dec]
    dec_prices.sort()
    dec_vals = [p for _, p in dec_prices]
    for i in range(1, len(dec_vals)):
        dec_mom_pct.append(abs((dec_vals[i] - dec_vals[i-1]) / dec_vals[i-1] * 100))
    if dec_mom_pct:
        decade_volatility[dec] = sum(dec_mom_pct) / len(dec_mom_pct)

# ── Rolling 12-month volatility ────────────────────────────────────────────
rolling_vol_12 = []
for i in range(11, n):
    window = prices[i - 11:i + 1]
    w_mean = sum(window) / 12
    w_std = math.sqrt(sum((x - w_mean) ** 2 for x in window) / 12)
    rolling_vol_12.append({'date': dates[i], 'std': w_std})

# ── Top 10 MoM shocks ──────────────────────────────────────────────────────
top_mom_increases = sorted(mom_changes, key=lambda x: -x['abs'])[:10]
top_mom_decreases = sorted(mom_changes, key=lambda x: x['abs'])[:10]

